-- Demo account for screenshots. Generated by supabase/seed/make_demo_seed.py; edit that, not this.
-- Set the demo account's handle below (and the friends', if different), then run it all.
do $$
declare
  demo uuid := (select id from public.profiles where handle = '__DEMO_HANDLE__');
  pal uuid := (select id from public.profiles where handle = 'georgechara');
  pal2 uuid := (select id from public.profiles where handle = 'georgechara_test');
  m uuid;
  g uuid;
  c uuid;
  l uuid;
begin
  if demo is null then raise exception 'No profile with the handle __DEMO_HANDLE__. Create the account in the app and pick that handle first.'; end if;

  -- A clean slate for the demo account only.
  delete from public.live_scores where user_id = demo;
  delete from public.activity where user_id = demo or dedupe_key like 'seed:%';
  delete from public.groups where owner = demo;
  delete from public.conversations where kind = 'direct' and (pair_low = demo or pair_high = demo);
  delete from public.matches where user_id = demo or (opponent_id = demo and user_id in (pal, pal2));
  delete from public.routine_score_entries where user_id = demo;
  delete from public.session_logs where user_id = demo;
  delete from public.session_templates where user_id = demo;
  delete from public.practice_plans where user_id = demo;
  delete from public.routine_bests where user_id = demo;
  delete from public.friendships where requester = demo or addressee = demo;

  -- Friends with the other accounts.
  if pal is not null then
    insert into public.friendships (requester, addressee, status, created_at, responded_at)
      values (demo, pal, 'accepted', now() - interval '60 days', now() - interval '60 days');
  end if;
  if pal2 is not null then
    insert into public.friendships (requester, addressee, status, created_at, responded_at)
      values (pal2, demo, 'accepted', now() - interval '40 days', now() - interval '40 days');
  end if;

  -- The monthly match limit stamps every new match with now() and would stop a free account at 12;
  -- it is off only while these go in, so they keep their real dates. It is back on at the end.
  alter table public.matches disable trigger trg_matches_subscription_limit;
  -- Matches over the last ten weeks, most scored live frame by frame.
  insert into public.matches (user_id, opponent_name, opponent_id, opponent_status, date, location, match_type, format,
